/** One label+value pair for [StatGrid]. `valueColor` defaults to plain `onSurface` when null (most stats aren't signal-colored). */
data class StatItem(val value: String, val label: String, val valueColor: Color? = null)

/**
 * 2026-09-06 -- prototyped on `Macro`/`Fundamentals` first, then rolled out to every metric-grid
 * card on Stock Detail (`MomentumAndTrend`, `Returns`, `HeadlineMetricsStrip`, `KeyLevels`) once
 * confirmed. Replaces the `FlowRow` + `Modifier.width(detail_stat_width)` pattern those files had
 * each hand-rolled independently (`HeadlineMetricsStrip` used a bare `Row(SpaceBetween)` instead;
 * `KeyLevels` used `Row(fillMaxWidth)` + `weight(1f)` in hardcoded pairs -- see its own call sites,
 * which still call `StatGrid` twice with `columns = 2` to preserve its two independent stat
 * pairings rather than one flat chunked-by-3 list): a fixed 96dp cell reads fine when every value
 * is a short number, but a stat whose value is a full word or a min–max range (`Macro`'s Rate
 * Sensitive, e.g. "MODERATE NEGATIVE"; Fundamentals' 5Y PE range) either cramps inside that width
 * or wraps awkwardly, and a lone leftover stat in the last row sits narrow and left-aligned with
 * empty space beside it instead of using the row it has to itself. Still not written into
 * `docs/theming-system/card-heading-conventions.md` as a formal convention -- ask before assuming
 * every future stat grid elsewhere in the app should reach for this without checking first.
 *
 * Chunks [stats] into rows of [columns] (3 by default) and gives every cell in a row equal
 * `Modifier.weight(1f)` width instead of a fixed dp value -- a full row of 3 divides evenly; a
 * partial last row (1 or 2 items) still divides *that row's* width evenly among however many are
 * actually in it, so a lone leftover stat expands to fill the whole row rather than staying
 * pinned to a narrow fixed column. Left-aligned by default (`Column`'s own alignment), matching
 * every other stat cell in the app.
 */
@Composable
fun StatGrid(stats: List<StatItem>, modifier: Modifier = Modifier, columns: Int = 3) {
    if (stats.isEmpty()) return

    Column(modifier = modifier, verticalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_medium))) {
        stats.chunked(columns).forEach { row ->
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(dimensionResource(id = R.dimen.padding_xlarge))
            ) {
                row.forEach { item ->
                    StatCell(item, modifier = Modifier.weight(1f))
                }
            }
        }
    }
}

@Composable
private fun StatCell(item: StatItem, modifier: Modifier = Modifier) {
    Column(modifier = modifier) {
        Text(
            text = item.value,
            style = MaterialTheme.typography.titleMedium.copy(fontWeight = FontWeight.Bold),
            color = item.valueColor ?: MaterialTheme.colorScheme.onSurface
        )
        Text(
            text = item.label,
            style = MaterialTheme.typography.labelSmall,
            color = LocalPulseColors.current.onSurfaceMuted
        )
    }
}

